import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/PositionEmbeddings.html","title":"PositionEmbeddings","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.75,"words":825},"filePathRelative":"PositionEmbeddings.md"}`),a={name:`PositionEmbeddings.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="positionembeddings" tabindex="-1"><a class="header-anchor" href="#positionembeddings"><span>PositionEmbeddings</span></a></h1><p><a href="./Transformer.html">Transformer</a>や<a href="./ConvS2S.html">ConvS2S</a>で使われている、位置情報をトークンの値と独立に判断するための仕組み。</p><ul><li><a href="./WhatDoPositionEmbeddingsLearn.html">WhatDoPositionEmbeddingsLearn</a> 学習されたPositionEmbeddingsの内容などを調査、ただし調査方法が少し微妙。</li><li><a href="./OnPositionEmbeddingsInBERT.html">OnPositionEmbeddingsInBERT</a> BERTにいろんなPEを適用してGLUEとかSQuADのスコアを見たり最初のアテンションの重みを評価したり。</li><li><a href="./RoPE.html">RoPE</a></li></ul><h2 id="lxdの行列をindexでルックアップして学習-convs2s-bert" tabindex="-1"><a class="header-anchor" href="#lxdの行列をindexでルックアップして学習-convs2s-bert"><span>LxDの行列をindexでルックアップして学習（ConvS2S, BERT）</span></a></h2><p><a href="./ConvS2S.html">ConvS2S</a>のPositionEmbeddingsの周辺の話。</p><p>論文では詳細は述べていないが、以下の実装を見ると</p><ul><li><a href="https://github.com/facebookresearch/fairseq/blob/main/fairseq/modules/learned_positional_embedding.py#L15" target="_blank" rel="noopener noreferrer">fairseq/fairseq/modules/learned_positional_embedding.py at main · facebookresearch/fairseq</a></li></ul><p>単なるintのindexでWをlookupしているようで、そのWを学習する感じになっている。通常のembeddingと同じ計算だな。 上の実装には<a href="./Transformer.html">Transformer</a>で提唱されたsinの奴も入っているが。</p><p>なお、positional embedding無しでもそこそこスコアはでているので、これが無いと全然駄目でも無さそう。BoWになるはずなんだが。論文のテーブル4に以下のスコアがある。</p><table><thead><tr><th>項目</th><th>BLUE</th></tr></thead><tbody><tr><td>両方にpositional embedding</td><td>21.7</td></tr><tr><td>targetだけpositional embedding</td><td>21.3</td></tr><tr><td>sourceだけpositional embedding</td><td>21.5</td></tr><tr><td>両方無し</td><td>21.2</td></tr></tbody></table><p>sourceの方が影響はでかそう。これはtargetの方は現在のトークンと一つ前のトークンという関係自体はモデル構造に入るため、ある程度は重要な位置的なものは織り込めるからかな。</p><p><a href="./BERT.html">BERT</a>でも、論文には詳細は書いていないが実装を見ると、512個のD次元のベクトルを単に学習させている。</p><p><a href="https://github.com/google-research/bert/blob/master/modeling.py?utm_source=chatgpt.com#L492C7-L492C31" target="_blank" rel="noopener noreferrer">bert/modeling.py at master · google-research/bert</a></p><h3 id="sinusoidal-vs-learned-embeddings" tabindex="-1"><a class="header-anchor" href="#sinusoidal-vs-learned-embeddings"><span>sinusoidal vs learned embeddings</span></a></h3><p><a href="./Transformer.html">Transformer</a>の論文のTable 3の(E)に学習するケースのスコアが載っていて、sinusoidalとほとんど同じ（少し学習する方が落ちる）という結果が載っている。 <a href="./OnPositionEmbeddingsInBERT.html">OnPositionEmbeddingsInBERT</a>ではlearnedの方が優秀そうなのでタスクによりそう。</p><h2 id="原論文から解き明かす生成aiの演習問題3-1-sinusoidalの相対位置" tabindex="-1"><a class="header-anchor" href="#原論文から解き明かす生成aiの演習問題3-1-sinusoidalの相対位置"><span>原論文から解き明かす生成AIの演習問題3.1(sinusoidalの相対位置)</span></a></h2><p><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>の演習問題3.1に、<a href="./Transformer.html">Transformer</a>のポジショナルエンコーディングが相対的な位置関係を把握しやすいというメリットがあるという事を示す問題があるのでやってみよう。</p><p>まずp+kを加法定理で開く事で、pの線形結合の形で書ける。</p><p><img src="/RandomThoughts/assets/0000-C42DhRGJ.png" alt="imgs/PositionEmbeddings/0000.png"></p><p>これでpの線形結合の形で書ける事が証明出来た（ちょっとpを右に寄せてないので見づらいが、まぁ分かるだろう）。</p><p>次にp+kとpの間の相対的な位置関係を調べるために、<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><msub><mi>E</mi><mrow><mi>p</mi><mo>+</mo><mi>k</mi></mrow></msub><mo>−</mo><mi>P</mi><msub><mi>E</mi><mi>p</mi></msub></mrow><annotation encoding="application/x-tex">PE_{p+k} - PE_{p}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> を計算してみる。2iと2i+1を調べてみれば十分だろう。</p><p><img src="/RandomThoughts/assets/0001-BzLqR4bE.png" alt="imgs/PositionEmbeddings/0001.png"></p><p>ここで、Aはkのみで、Bはpのみとなっている。 そしてpositional encodingは違う位置のものが区別出来るような値になっていると期待出来るので、pを起点として既知とすると、このAの部分を分離出来て、 Aからkを知る事が出来る（ような値がpositional encodingに期待されるもの）。</p><p>これが答えになっているかは少し微妙なので、もう少し周辺的なことを考えてみる。 これはようするに、並進対称性のようなものを持たせられる、という話だと思う。 10個目のトークンと13個目のトークンの間の関係を学習した時、違う例文の100個目と103個目にも同じ関係を適用出来るようなモデルに出来る、という事だと思う。 これは修飾語だとか修飾節、語群自体が主語と目的語のように違う役割を果たすが語群内での修飾関係が同じ、 みたいな事を学習出来るようなモデルになっているか？という話だと思う。</p><p>これは画像解析で、CNNが良いとされていた根拠にもなっていて、画像内に対象オブジェクトが少し移動している時でもちゃんんと認識出来るという事を保証する数学的な性質。</p><p>さて、Transformer型のモデルで異なる位置の特徴量の線形和を考えた時に、いつも3個右隣のトークンとの間に似たような関係が見られる、としたとしよう。 ただしどこのトークンかはトレーニングセットの文章ごとに異なる。 この時に、値のみからこの3個右隣、という事を取り出せるのか？というのが題意だと思うが、これはそんなに自明でもない。</p><p>positional encodingは位置ごとに独立っぽい値になっていて、値のみからどこの位置かの雰囲気が分かると期待されるものだ。 そしてp+kがpの線形結合で表せる事から、p+kは、「p+kの雰囲気を感じつつpの雰囲気も感じる」ような値になっていると期待出来る。 また、kの線形結合にもなっているので、「kの雰囲気も感じる」事が出来ると期待は出来る。 そして学習の時にkの雰囲気が重要な情報になっているとすると、このkを取り出せる事は出来るかもしれない。</p><p>ただ本当に出来るかは良く分からない。少し考えてみよう。図の式で、左辺が与えられた時に、右辺が学習出来るか、という話に思う。 Aの所を未知の2x2行列だとする。Bのpも学習する必要がある。 左辺がいろいろ与えられた時に、このpの値をいろいろ調整していつも同じAになるように出来るか？という学習になる。 結構難しい気はする。</p><p>ただ、kの線形結合でも表せている事から考えると、positional encodingが基本的な演算をしても位置っぽさが残るという元の期待を満たされているとするなら、 kを学習は出来るはずと言えそうだ。</p><p>これは証明というよりは、数学的にはこういう分解が出来る、以上の事は言えず、あとは実験で比較してみるしかないんじゃないかなぁ。 逆象が存在するかもかなり自明ではないし、kと近いようなpの値を間違えて相対位置と勘違いしないような演算が作れるか、とかはかなり自明ではない。</p><p>ChatGPTに質問して、以下の論文を教えてもらう。<a href="./WhatDoPositionEmbeddingsLearn.html">WhatDoPositionEmbeddingsLearn</a></p><h2 id="sinusoidalの値の確認-演習問題3-2" tabindex="-1"><a class="header-anchor" href="#sinusoidalの値の確認-演習問題3-2"><span>Sinusoidalの値の確認(演習問題3.2)</span></a></h2><p><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>の演習問題3.2はsinusoidalのembeddingsが実際にどういう値になっているかを確認せよ、というもの。 annotated transformerに同じようなのあったが、自分でやってみるか。</p><p><a href="https://colab.research.google.com/drive/1I0Xk6PG1G-KggKCBR7Ubark8PnQ9awEH?usp=sharing" target="_blank" rel="noopener noreferrer">colab: SinusoidalなPositionEmbeddingsの確認.ipynb</a></p><p>高次元の方がゆるやかになって、低次元の方が高周波になっている。 低次元は近傍の前後関係を、高次元は絶対的な位置の雰囲気を伝えるのだろう。</p><h2 id="sinusoidalのスケールの確認-演習問題3-3" tabindex="-1"><a class="header-anchor" href="#sinusoidalのスケールの確認-演習問題3-3"><span>Sinusoidalのスケールの確認（演習問題3.3）</span></a></h2><p>上のcolabで一緒にやっている。16、これは256のルートなので、つまりd_model/2のルートになっている。 これと合わせるために式3.4ではトークン側のembeddingにルートdを掛けている（なんでルート2で割らないのかは不明だが）。</p>`,37)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};